    "explanation": "【公式アーキテクチャ解説】\n正解は「エージェントの会話履歴と中断時のツール呼び出しコンテキストを外部DBにシリアライズ保存し、Webhook通知時に復元再開する設計」です。\n\n長時間の非同期承認（HITL）においては、エージェントを「ステートレス」に設計するのがエンタープライズの鉄則です。\nツール実行直前の状態（Message履歴、保留中のTool Call ID、引数等）を一意な `approval_token` と共にRedisやDynamoDB等の永続層に保存してプロセスを一旦正常終了させます。人間が承認した際にWebhook等でワーカーを起動し、DBから状態を復元してツールの実行を再開（Resume）します。\n\n⚠️ 引っかけポイント: メモリ上でPromiseを保留したりプロセスをブロックし続ける設計は、サーバー再起動やスケールインでセッションが消失するため、本番運用ではアンチパターンです。",
