    "explanation": "【公式アーキテクチャ解説】\n正解は「通常のpull_requestトリガー（読み取り専用権限・シークレット非公開）を使用するか、2段階の分離ワークフローを採用する設計」です。\n\nGitHub Actionsにおける悪名高いセキュリティ脆弱性「PwnRequest / Pwned Pipeline」への対策です。\n`pull_request_target` は親リポジトリのシークレットにアクセスできる特権コンテキストで動作するため、フォーク元のコードをそのまま `git checkout` して実行すると、攻撃者のコードが特権環境で実行されてしまいます。\n安全なアーキテクチャは：\n1. フォーク元のPRでは、権限を持たない通常の `pull_request` イベントを使用する（シークレットへのアクセスがブロックされる）。\n2. AIレビュー等でAPIキーが必要な場合は、第1ジョブで差分テキスト（安全な文字列）のみをArtifactとして書き出し、第2ジョブ（特権分離された環境）で差分テキストのみを入力としてAIに渡す「2段階ワークフロー」を採用し、フォーク元の任意のスクリプトが特権環境で実行されることを防ぎます。\n\n⚠️ 引っかけポイント: 管理者権限の付与は攻撃者に鍵を渡す行為であり、監視カメラや全廃は非現実的です。",
