    "question": "【シナリオ：構造化データ抽出】\n前提: 抽出パイプラインのバックエンドにおいて、Claude が出力した JSON を Pydantic（Python）または Zod（TypeScript）を用いて厳格にスキーマ検証（型チェック、必須キー検証、数値範囲バリデーション）している。\n\n状況・課題:\n1,000件に数件の割合で、日付フォーマットが `YYYY-MM-DD` ではなく `YYYY/MM/DD` になっていたり、数値であるべきフィールドに「未定」という文字列が入るなどのスキーマ違反が発生し、バリデーション例外でパイプラインが停止する。\n\n問い:\nスキーマ検証エラーが発生した際、人手を介さずに全自動で正しいスキーマ適合JSONへ修復・再生成させるための自己修復（Self-Correction）アーキテクチャはどれか？",
